10	// Types
11	// ---------------------------------------------------------------------------
12	
13	export interface BillingContext {
14	  admin: { graphql: (query: string, options?: { variables?: Record<string, unknown> }) => Promise<{ json: () => Promise<unknown> }> };
15	  session: { shop: string };
16	}
17	
18	interface AppSubscriptionCreateResponse {
19	  data: {
20	    appSubscriptionCreate: {
21	      appSubscription: { id: string } | null;
22	      confirmationUrl: string | null;
23	      userErrors: { field: string; message: string }[];
24	    };
25	  };
26	}
27	
28	interface AppSubscriptionCancelResponse {
29	  data: {
30	    appSubscriptionCancel: {
31	      appSubscription: { id: string; status: string } | null;
32	      userErrors: { field: string; message: string }[];
33	    };
34	  };
35	}
36	
37	interface CurrentAppInstallationResponse {
38	  data: {
39	    currentAppInstallation: {
40	      activeSubscriptions: {
41	        id: string;
42	        name: string;
43	        status: string;
44	        createdAt: string;
45	        currentPeriodEnd: string | null;
46	        test: boolean;
47	        lineItems: {
48	          plan: {
49	            pricingDetails:
50	              | { price: { amount: string; currencyCode: string } }
51	              | { interval: string; base: { amount: string; currencyCode: string } };
52	          };
53	        }[];
54	      }[];
55	    };
56	  };
57	}
