121	// ---------------------------------------------------------------------------
122	// Convert height/weight to inches/lbs (imperial baseline)
123	// ---------------------------------------------------------------------------
124	
125	function toImperial(
126	  height: number,
127	  weight: number,
128	  unit: RecommendRequestBody["unit"],
129	): { heightIn: number; weightLbs: number } {
130	  if (unit === "imperial") {
131	    return { heightIn: height, weightLbs: weight };
132	  }
133	  // metric: height in cm, weight in kg
134	  return {
135	    heightIn: height / 2.54,
136	    weightLbs: weight * 2.20462,
137	  };
138	}
