1	import type { LoaderFunctionArgs } from "react-router";
2	import db from "../db.server";
3	
4	// ---------------------------------------------------------------------------
5	// CORS
6	// ---------------------------------------------------------------------------
7	
8	const CORS_HEADERS = {
9	  "Access-Control-Allow-Origin": "*",
10	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
11	  "Access-Control-Allow-Headers": "Content-Type",
12	};
13	
14	// ---------------------------------------------------------------------------
15	// Validation
16	// ---------------------------------------------------------------------------
17	
18	const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
19	
20	// ---------------------------------------------------------------------------
21	// Types
22	// ---------------------------------------------------------------------------
23	
24	interface ChartData {
25	  headers: string[];
26	  units: { default: string; available: string[] };
27	  rows: Record<string, string>[];
28	}
29	
30	interface SizeChartResponse {
31	  id: string;
32	  name: string;
33	  category: string;
34	  type: string;
35	  data: ChartData;
36	  assignmentType?: string;
37	}
38	
39	// ---------------------------------------------------------------------------
40	// Assignment priority lookup
41	// Priority: product (1) > collection (2) > product_type (3) > tag (4) > all (5)
42	// ---------------------------------------------------------------------------
43	
44	const ASSIGNMENT_PRIORITY: Record<string, number> = {
45	  product: 1,
46	  collection: 2,
47	  product_type: 3,
48	  tag: 4,
49	  all: 5,
50	};
51	
52	// ---------------------------------------------------------------------------
53	// Loader — GET /api/size-chart
54	// Query params: shop (required), productId?, collectionId?, chartId?
55	// ---------------------------------------------------------------------------
56	
57	export const loader = async ({ request }: LoaderFunctionArgs) => {
58	  if (request.method === "OPTIONS") {
59	    return new Response(null, { status: 204, headers: CORS_HEADERS });
60	  }
61	
62	  const url = new URL(request.url);
63	  const shop = url.searchParams.get("shop");
64	  const chartId = url.searchParams.get("chartId");
65	  const productId = url.searchParams.get("productId");
66	  const collectionId = url.searchParams.get("collectionId");
67	
68	  // Validate shop param
69	  if (!shop || !SHOP_RE.test(shop)) {
70	    return Response.json(
71	      { error: "Invalid or missing shop parameter" },
72	      { status: 400, headers: CORS_HEADERS },
73	    );
74	  }
75	
76	  try {
77	    // Direct lookup by chartId
78	    if (chartId) {
79	      const chart = await db.sizeChart.findFirst({
80	        where: { id: chartId, shop, status: "active" },
81	      });
82	
83	      if (!chart) {
84	        return Response.json(
85	          { error: "Chart not found" },
86	          { status: 404, headers: CORS_HEADERS },
87	        );
88	      }
89	
90	      const parsedData = parseChartData(chart.data);
91	      const response: SizeChartResponse = {
92	        id: chart.id,
93	        name: chart.name,
94	        category: chart.category,
95	        type: chart.type,
96	        data: parsedData,
97	      };
98	
99	      return Response.json(response, { headers: CORS_HEADERS });
100	    }
101	
102	    // Build lookup values from provided params
103	    // We'll fetch all active assignments for this shop and filter in priority order
104	    const lookupValues: Array<{ type: string; value: string }> = [];
105	
106	    if (productId) {
107	      lookupValues.push({ type: "product", value: productId });
108	    }
109	    if (collectionId) {
110	      lookupValues.push({ type: "collection", value: collectionId });
111	    }
112	
113	    if (lookupValues.length === 0) {
114	      return Response.json(
115	        { error: "At least one of chartId, productId, or collectionId is required" },
116	        { status: 400, headers: CORS_HEADERS },
117	      );
118	    }
119	
120	    // Always include the wildcard "all" fallback
121	    lookupValues.push({ type: "all", value: "*" });
122	
123	    // Fetch all assignments that could match, ordered by the chart's status
124	    const assignments = await db.chartAssignment.findMany({
125	      where: {
126	        shop,
127	        OR: lookupValues.map(({ type, value }) => ({
128	          assignmentType: type,
129	          assignmentValue: value,
130	        })),
131	      },
132	      include: {
133	        sizeChart: true,
134	      },
135	    });
136	
137	    // Filter to only active charts and pick by priority
138	    const activeAssignments = assignments.filter(
139	      (a) => a.sizeChart.status === "active",
140	    );
141	
142	    if (activeAssignments.length === 0) {
143	      return Response.json(
144	        { error: "No size chart found for the given product" },
145	        { status: 404, headers: CORS_HEADERS },
146	      );
147	    }
148	
149	    // Sort by priority — lowest number = highest priority
150	    activeAssignments.sort((a, b) => {
151	      const pa = ASSIGNMENT_PRIORITY[a.assignmentType] ?? 99;
152	      const pb = ASSIGNMENT_PRIORITY[b.assignmentType] ?? 99;
153	      return pa - pb;
154	    });
155	
156	    const best = activeAssignments[0];
157	    const parsedData = parseChartData(best.sizeChart.data);
158	
159	    const response: SizeChartResponse = {
160	      id: best.sizeChart.id,
161	      name: best.sizeChart.name,
162	      category: best.sizeChart.category,
163	      type: best.sizeChart.type,
164	      data: parsedData,
165	      assignmentType: best.assignmentType,
166	    };
167	
168	    return Response.json(response, { headers: CORS_HEADERS });
169	  } catch (error) {
170	    console.error("[api.size-chart]", error);
171	    return Response.json(
172	      { error: "Unable to load size chart. Please try again." },
173	      { status: 500, headers: CORS_HEADERS },
174	    );
175	  }
176	};
177	
178	// ---------------------------------------------------------------------------
179	// Helpers
180	// ---------------------------------------------------------------------------
181	
182	function parseChartData(raw: string): ChartData {
183	  try {
184	    const parsed = JSON.parse(raw) as unknown;
185	    if (
186	      parsed !== null &&
187	      typeof parsed === "object" &&
188	      !Array.isArray(parsed)
189	    ) {
190	      const obj = parsed as Record<string, unknown>;
191	      return {
192	        headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
193	        units:
194	          obj.units !== null &&
195	          typeof obj.units === "object" &&
196	          !Array.isArray(obj.units)
197	            ? (obj.units as { default: string; available: string[] })
198	            : { default: "in", available: ["in", "cm"] },
199	        rows: Array.isArray(obj.rows)
200	          ? (obj.rows as Record<string, string>[])
201	          : [],
202	      };
203	    }
204	  } catch {
205	    // fall through to default
206	  }
207	  return {
208	    headers: [],
209	    units: { default: "in", available: ["in", "cm"] },
210	    rows: [],
211	  };
212	}
